insert into public.vow_knowledge (domain,topic,title,content,principles,recommended_actions,metrics,cautions,source_url,active)
values
('fitness','walking','Walking and aerobic base','Regular low-to-moderate intensity movement can build an aerobic base and support consistency. Progress duration gradually and keep effort appropriate to the person.','["Consistency matters more than occasional large efforts","Progress gradually","Use effort and recovery to guide workload"]'::jsonb,'["Start with repeatable sessions","Increase duration before adding complexity","Record duration and perceived effort"]'::jsonb,'["minutes","sessions_per_week","perceived_effort"]'::jsonb,'["Pain or unusual symptoms warrant appropriate professional advice","Avoid sudden workload spikes"]'::jsonb,null,true),
('fitness','swimming','Swimming skill development','Swimming combines technique, coordination, breathing and conditioning. Skill practice should be separated from harder conditioning when possible.','["Technique quality comes before adding fatigue","Frequent practice supports motor learning","Progress one constraint at a time"]'::jsonb,'["Practise one technical focus per session","Use short repeatable drills","Track distance, time and perceived effort"]'::jsonb,'["distance","time","technical_focus"]'::jsonb,'["Do not push through pain","Open-water conditions require appropriate supervision and safety planning"]'::jsonb,null,true),
('fitness','mobility','Mobility practice','Mobility work is most useful when it targets movements relevant to the goal and is performed consistently.','["Specificity matters","Consistency beats occasional long sessions","Control matters as well as range"]'::jsonb,'["Identify limiting movements","Use controlled repetitions","Reassess the movement after several weeks"]'::jsonb,'["range_of_motion","session_frequency","movement_quality"]'::jsonb,'["Do not force painful ranges"]'::jsonb,null,true),
('fitness','recovery','Training recovery','Adaptation requires recovery as well as training. Sleep, nutrition, rest days and sensible workload progression all influence consistency.','["Training stress and recovery must be balanced","Fatigue is information","Long-term consistency is the priority"]'::jsonb,'["Keep harder sessions separated when possible","Monitor sleep and fatigue","Reduce workload when recovery is clearly poor"]'::jsonb,'["sleep","fatigue","rest_days","training_load"]'::jsonb,'["Avoid treating exhaustion as a requirement for progress"]'::jsonb,null,true),
('fitness','cycling','Cycling progression','Cycling endurance improves through repeatable aerobic sessions, gradual duration increases and appropriate recovery.','["Build volume gradually","Use easy and harder work deliberately","Track what you actually complete"]'::jsonb,'["Establish a comfortable baseline ride","Add time in small steps","Use occasional quality sessions once a base exists"]'::jsonb,'["ride_duration","distance","effort"]'::jsonb,'["Equipment and road conditions affect training demands"]'::jsonb,null,true),
('education','physics','Physics problem solving','Physics improves when concepts are connected to equations, diagrams, units and worked problem solving.','["Understand the model before calculating","Units are part of the reasoning","Use errors to identify misconceptions"]'::jsonb,'["Draw a diagram","List knowns and unknowns","Choose an equation from the physical model","Check units and magnitude"]'::jsonb,'["accuracy","time_per_problem","error_types"]'::jsonb,'["Do not memorise equations without understanding variables and assumptions"]'::jsonb,null,true),
('education','chemistry','Chemistry learning','Chemistry benefits from combining conceptual models, equations, practical interpretation and repeated retrieval.','["Connect microscopic and macroscopic explanations","Practise calculations","Correct misconceptions explicitly"]'::jsonb,'["Use retrieval questions","Practise balanced equations and calculations","Explain why an answer makes sense"]'::jsonb,'["retrieval_accuracy","calculation_accuracy","topic_coverage"]'::jsonb,'["Watch units, significant figures and chemical conventions"]'::jsonb,null,true),
('education','biology','Biology learning','Biology requires both factual retrieval and understanding of processes, systems and relationships.','["Retrieve before rereading","Use diagrams for processes","Link structure to function"]'::jsonb,'["Create short recall prompts","Practise explaining processes from memory","Use exam questions to expose gaps"]'::jsonb,'["recall_accuracy","exam_accuracy","topic_coverage"]'::jsonb,'["Avoid confusing familiarity with mastery"]'::jsonb,null,true),
('education','computer_science','Computer science learning','Computer science develops through understanding concepts, writing code, debugging and explaining solutions.','["Practise beats passive reading","Debugging is part of learning","Small working programs build confidence"]'::jsonb,'["Build small programs","Predict outputs before running code","Keep an error log","Refactor working solutions"]'::jsonb,'["bugs_fixed","projects_completed","concept_recall"]'::jsonb,'["Do not copy solutions without understanding them"]'::jsonb,null,true),
('education','geography','Geography learning','Geography combines place knowledge, processes, data interpretation, evaluation and case-study evidence.','["Connect processes to evidence","Practise data interpretation","Use case studies purposefully"]'::jsonb,'["Practise maps and graphs","Build concise case-study evidence banks","Answer timed evaluation questions"]'::jsonb,'["case_study_recall","data_question_accuracy","timed_score"]'::jsonb,'["Do not memorise disconnected facts"]'::jsonb,null,true),
('education','essay_writing','Essay writing','Strong essays make a clear claim, support it with relevant evidence and explain why the evidence matters.','["Argument drives structure","Evidence must be relevant","Explanation should connect evidence to the claim"]'::jsonb,'["Write a one-sentence thesis","Plan paragraph claims","Add evidence and analysis","Edit for clarity"]'::jsonb,'["completed_drafts","feedback_items_fixed","timed_writing"]'::jsonb,'["Do not optimise only for word count"]'::jsonb,null,true),
('education','revision','Revision systems','Effective revision combines retrieval, spaced review, interleaving and targeted correction of errors.','["Retrieve before reviewing","Space repeated exposure","Prioritise weak areas"]'::jsonb,'["Use short recall sessions","Schedule revisits","Maintain an error list","Mix related problem types"]'::jsonb,'["retrieval_score","review_frequency","error_rate"]'::jsonb,'["Long passive rereading sessions can create false confidence"]'::jsonb,null,true),
('learning','skill_acquisition','Skill acquisition','Complex skills improve through deliberate practice focused on a specific subskill with feedback.','["Break skills into components","Practise at an appropriate difficulty","Use feedback quickly"]'::jsonb,'["Choose one subskill","Define a measurable practice target","Review performance after each block"]'::jsonb,'["successful_repetitions","accuracy","practice_minutes"]'::jsonb,'["Avoid changing several variables at once"]'::jsonb,null,true),
('learning','memory','Memory and recall','Memory strengthens when information is actively retrieved over time rather than repeatedly reread.','["Retrieval creates useful difficulty","Spacing supports retention","Feedback corrects errors"]'::jsonb,'["Use flashcards selectively","Self-test without notes","Repeat difficult items more often"]'::jsonb,'["recall_accuracy","retention_after_delay"]'::jsonb,'["Flashcards are less useful when they test trivial recognition only"]'::jsonb,null,true),
('learning','deliberate_practice','Deliberate practice','Deliberate practice targets a narrow weakness, requires attention and includes feedback or correction.','["Target weaknesses","Keep practice purposeful","Use feedback"]'::jsonb,'["Define the exact performance gap","Practise a manageable chunk","Record the correction"]'::jsonb,'["error_rate","quality_repetitions","feedback_items"]'::jsonb,'["High volume without attention is not automatically deliberate practice"]'::jsonb,null,true),
('productivity','planning','Weekly planning','A useful weekly plan turns priorities into concrete actions while leaving capacity for interruptions.','["Choose a small number of priorities","Schedule important work","Leave recovery and buffer time"]'::jsonb,'["Select three high-value outcomes","Break them into next actions","Review the week before planning the next"]'::jsonb,'["priority_completion","planned_vs_actual","overdue_items"]'::jsonb,'["Do not fill every minute of the week"]'::jsonb,null,true),
('productivity','procrastination','Reducing procrastination','Starting becomes easier when the next action is specific, small and immediately available.','["Reduce activation energy","Define the first physical action","Use short starts"]'::jsonb,'["Write the next action in verb form","Start with five minutes","Remove one obvious distraction"]'::jsonb,'["start_latency","focused_minutes","completed_actions"]'::jsonb,'["Do not interpret procrastination as a fixed character trait"]'::jsonb,null,true),
('productivity','prioritisation','Prioritisation','Prioritisation means deciding what matters most under limited time and attention.','["Value and urgency are different","Trade-offs are unavoidable","A shorter list improves focus"]'::jsonb,'["Identify the outcome that matters most","Estimate effort","Defer or remove low-value work"]'::jsonb,'["high_value_tasks_completed","hours_on_priority"]'::jsonb,'["Avoid making everything a priority"]'::jsonb,null,true),
('productivity','digital_hygiene','Digital organisation','A simple system for files, notes and tasks reduces search costs and cognitive load.','["One trusted home per information type","Consistent naming","Regular cleanup"]'::jsonb,'["Create clear folders","Use predictable names","Archive completed material"]'::jsonb,'["search_time","inbox_size","overdue_items"]'::jsonb,'["Avoid complex systems that take more time to maintain than they save"]'::jsonb,null,true),
('personal_development','confidence','Building confidence','Confidence often grows from repeated evidence of capability, preparation and manageable exposure to challenges.','["Evidence beats empty reassurance","Preparation reduces uncertainty","Stretch gradually"]'::jsonb,'["Keep a record of completed challenges","Practise difficult situations","Increase difficulty gradually"]'::jsonb,'["challenges_completed","practice_frequency","self_rating"]'::jsonb,'["Do not make confidence depend on perfection"]'::jsonb,null,true),
('personal_development','discipline','Self-discipline','Reliable behaviour is easier when the desired action is clearly defined and environmental friction is reduced.','["Systems support willpower","Make good actions easy","Use routines"]'::jsonb,'["Prepare materials in advance","Attach actions to existing routines","Review adherence without self-punishment"]'::jsonb,'["adherence_rate","missed_actions","streaks"]'::jsonb,'["A missed day is information, not proof of failure"]'::jsonb,null,true),
('personal_development','decision_making','Decision making','Good decisions separate facts, assumptions, preferences, risks and reversible choices.','["Not all decisions need equal analysis","State assumptions","Prefer reversible experiments when appropriate"]'::jsonb,'["Define the decision","List constraints","Compare a small set of options","Choose a review point"]'::jsonb,'["decision_time","outcome_vs_prediction"]'::jsonb,'["Avoid false precision when evidence is weak"]'::jsonb,null,true),
('career','networking','Professional networking','Useful networking is based on genuine curiosity, clear communication and reciprocal value rather than collecting contacts.','["Quality relationships matter","Be specific about your interests","Follow up respectfully"]'::jsonb,'["Prepare a short introduction","Ask informed questions","Send concise follow-ups","Keep relationships warm over time"]'::jsonb,'["meaningful_conversations","follow_ups","new_connections"]'::jsonb,'["Avoid spammy or manipulative outreach"]'::jsonb,null,true),
('career','portfolio','Building a portfolio','A strong portfolio demonstrates outcomes, decisions, process and evidence of skill.','["Show work, not only claims","Explain decisions","Curate for the target opportunity"]'::jsonb,'["Choose a few strong projects","Document the problem and outcome","Add measurable evidence","Remove weak examples"]'::jsonb,'["projects_completed","portfolio_reviews","evidence_points"]'::jsonb,'["Do not exaggerate results"]'::jsonb,null,true),
('career','interviewing','Interview practice','Interview performance improves through role research, concise examples, rehearsal and thoughtful questions.','["Prepare evidence","Practise aloud","Answer the actual question"]'::jsonb,'["Prepare situation-action-result examples","Research the organisation","Record practice answers","Prepare questions"]'::jsonb,'["practice_sessions","answer_length","examples_prepared"]'::jsonb,'["Avoid memorising answers word-for-word"]'::jsonb,null,true),
('business','customer_research','Customer discovery','Good customer research tests assumptions about problems, behaviour and willingness to use a solution.','["Ask about real behaviour","Listen before pitching","Look for repeated patterns"]'::jsonb,'["Interview potential users","Ask about current alternatives","Record recurring problems","Test a narrow hypothesis"]'::jsonb,'["interviews","repeated_pain_points","experiment_results"]'::jsonb,'["Do not treat polite interest as proof of demand"]'::jsonb,null,true),
('business','mvp','Minimum viable product','An MVP is the smallest useful test of a key product assumption, not simply a low-quality version of the final product.','["Test the riskiest assumption","Keep scope narrow","Measure behaviour"]'::jsonb,'["Define one core user problem","Build the smallest test","Observe real usage","Iterate from evidence"]'::jsonb,'["time_to_test","active_users","conversion","retention"]'::jsonb,'["Avoid adding features before validating the core problem"]'::jsonb,null,true),
('business','marketing','Marketing fundamentals','Marketing connects a defined audience with a relevant value proposition through channels that can be measured and improved.','["Know the audience","Make the value proposition clear","Measure outcomes"]'::jsonb,'["Define one target segment","Write a clear proposition","Test one channel at a time","Track meaningful actions"]'::jsonb,'["reach","clicks","conversion","retention"]'::jsonb,'["Vanity metrics can hide weak product-market fit"]'::jsonb,null,true),
('business','project_management','Project management','Projects are easier to execute when scope, owners, dependencies, milestones and review points are explicit.','["Make work visible","Control scope","Review risks early"]'::jsonb,'["Define the outcome","Break work into deliverables","Assign ownership","Review blockers weekly"]'::jsonb,'["milestone_completion","blocked_items","schedule_variance"]'::jsonb,'["Avoid planning detail that will never be maintained"]'::jsonb,null,true),
('finance','saving','Goal-based saving','Saving works better when the target, time horizon and regular contribution are explicit.','["Automate consistency where possible","Separate needs from optional spending","Review progress regularly"]'::jsonb,'["Set a target amount","Choose a deadline","Calculate a realistic contribution","Track actual progress"]'::jsonb,'["saved_amount","contribution_rate","target_progress"]'::jsonb,'["Do not assume investment returns are guaranteed"]'::jsonb,null,true),
('finance','cashflow','Cash-flow management','Cash flow planning tracks when money arrives and when obligations are due, not just total income and spending.','["Timing matters","Plan for irregular costs","Keep a buffer"]'::jsonb,'["List recurring obligations","Map expected inflows and outflows","Review upcoming weeks"]'::jsonb,'["cash_balance","upcoming_obligations","buffer"]'::jsonb,'["Use conservative assumptions for uncertain income"]'::jsonb,null,true),
('finance','financial_literacy','Financial literacy','Financial decisions benefit from understanding fees, interest, risk, inflation, contracts and opportunity cost.','["Read the terms","Compare total cost","Understand risk before committing"]'::jsonb,'["Calculate total cost","Check fees and penalties","Separate facts from sales claims"]'::jsonb,'["total_cost","fee_rate","interest_rate"]'::jsonb,'["For important financial decisions, use appropriate qualified advice"]'::jsonb,null,true),
('technology','programming','Software project practice','Programming skills grow through building, debugging, testing and reviewing small systems.','["Make small changes","Test assumptions","Read errors carefully"]'::jsonb,'["Define a tiny feature","Write a test or verification step","Debug systematically","Refactor after it works"]'::jsonb,'["features_completed","bugs_fixed","test_coverage"]'::jsonb,'["Do not paste secrets into source code"]'::jsonb,null,true),
('technology','web_security','Web security basics','Secure web applications use least privilege, input validation, safe secret handling, authentication and row-level or server-side authorisation.','["Never trust client input","Keep secrets server-side","Authorise every sensitive operation"]'::jsonb,'["Validate inputs","Use parameterised queries","Keep privileged keys off clients","Audit access policies"]'::jsonb,'["auth_failures","security_findings","dependency_updates"]'::jsonb,'["Security controls must match the actual data and threat model"]'::jsonb,null,true),
('technology','databases','Database design','Good database design uses clear ownership, appropriate constraints, indexes for real query patterns and access control.','["Model relationships explicitly","Constrain invalid states","Optimise measured bottlenecks"]'::jsonb,'["Define primary and foreign keys","Add ownership checks","Index common filters","Review query plans when needed"]'::jsonb,'["query_latency","constraint_failures","index_usage"]'::jsonb,'["Indexes have maintenance and write costs"]'::jsonb,null,true),
('technology','ai','AI-assisted work','AI is most useful when paired with clear goals, good context, verification and human judgement.','["Treat generated content as a draft","Provide relevant context","Verify consequential claims"]'::jsonb,'["Define the desired output","Give constraints","Ask for structured results","Check important facts"]'::jsonb,'["verification_rate","revision_count","task_completion"]'::jsonb,'["AI can hallucinate, misunderstand context or produce overconfident answers"]'::jsonb,null,true),
('technology','version_control','Version control','Version control makes changes traceable and reversible when commits are focused and messages are clear.','["Commit coherent changes","Keep history understandable","Verify before release"]'::jsonb,'["Use small commits","Describe why a change was made","Review diffs","Tag stable releases"]'::jsonb,'["failed_builds","rollback_time","change_size"]'::jsonb,'["Never commit secrets or credentials"]'::jsonb,null,true),
('communication','writing','Clear writing','Clear writing uses a defined purpose, direct language, logical structure and enough context for the reader.','["Lead with the point","Use concrete language","Remove unnecessary repetition"]'::jsonb,'["State the purpose","Use short paragraphs","Edit for the reader","Read once from the recipient perspective"]'::jsonb,'["revision_count","reader_questions","message_length"]'::jsonb,'["Brevity should not remove necessary context"]'::jsonb,null,true),
('communication','listening','Active listening','Active listening involves attention, clarification and accurate reflection of what another person means.','["Listen before solving","Clarify ambiguity","Reflect key points"]'::jsonb,'["Ask open questions","Summarise what you heard","Check assumptions"]'::jsonb,'["clarifying_questions","misunderstandings"]'::jsonb,'["Listening does not require agreeing with everything said"]'::jsonb,null,true),
('communication','presentation','Presentations','Effective presentations guide attention through a clear narrative, useful visuals and rehearsed delivery.','["One core message","Structure before decoration","Rehearse transitions"]'::jsonb,'["Write the takeaway first","Limit each slide to a purpose","Practise aloud","Time the full presentation"]'::jsonb,'["rehearsals","duration","audience_questions"]'::jsonb,'["Do not overload slides with text"]'::jsonb,null,true),
