('travel','itinerary','Itinerary planning','Good itineraries balance priorities, travel time, opening constraints, budget and recovery time.','["Avoid impossible schedules","Cluster nearby activities","Keep contingency time"]'::jsonb,'["List fixed commitments","Estimate transfer time","Add buffers","Keep a short priority list"]'::jsonb,'["planned_activities","buffer_time","budget"]'::jsonb,'["Transport delays and local constraints can invalidate tight plans"]'::jsonb,null,true),
('travel','packing','Travel preparation','Packing works best when based on activities, weather, duration, laundry access and document requirements.','["Pack for the actual itinerary","Keep essentials accessible","Check documents early"]'::jsonb,'["Create a reusable checklist","Check weather","Separate travel-day essentials","Verify documents"]'::jsonb,'["items_packed","last_minute_items"]'::jsonb,'["Requirements vary by destination and traveller"]'::jsonb,null,true),
('life_admin','checklists','Checklists','Checklists reduce omission errors for repeatable tasks with multiple dependencies.','["Externalise memory","Put critical checks in order","Update after mistakes"]'::jsonb,'["Build checklists for recurring processes","Mark high-risk steps","Review after completion"]'::jsonb,'["missed_steps","completion_time"]'::jsonb,'["Keep checklists short enough to use"]'::jsonb,null,true),
