('wellbeing','stress','Stress management','Stress is easier to manage when demands are identified, controllable actions are separated from uncontrollable factors and recovery is protected.','["Name the demand","Act on what is controllable","Protect recovery"]'::jsonb,'["List current stressors","Choose one controllable action","Schedule recovery","Ask for support when needed"]'::jsonb,'["stress_rating","recovery_time","completed_actions"]'::jsonb,'["Do not treat severe or persistent distress as a productivity problem"]'::jsonb,null,true),
